const raw = $json.chatInput;

// A question must exist and be a string
if (raw === undefined || raw === null || typeof raw !== 'string') {
  return { valid: false, error: 'Question cannot be empty' };
}

// Trim whitespace and confirm it is not empty
const cleaned = raw.trim();
if (cleaned === '') {
  return { valid: false, error: 'Question cannot be empty' };
}

return { valid: true, question: cleaned };

const question = $json.question;
const lower = question.toLowerCase();
const received_at = new Date().toISOString();

// RULE 3 — Priority detection
const urgentTerms = ['urgent', 'urgently', 'emergency', 'immediately', 'critical'];
const priority = urgentTerms.some(function (t) { return lower.includes(t); }) ? 'High' : 'Normal';

// RULE 1 — Request length (too short)
if (question.length < 5) {
  return {
    question: question,
    request_type: 'unknown',
    priority: priority,
    status: 'rejected',
    reason: 'Question is too short',
    received_at: received_at,
  };
}

// RULE 2 — Company knowledge detection
const knowledgeTerms = [
  'company', 'policy', 'policies', 'sop', 'procedure', 'hr', 'leave',
  'holiday', 'attendance', 'employee', 'work', 'office', 'remote',
  'salary', 'benefits', 'security', 'onboarding', 'internship',
  'working hours', 'guidelines'
];
const isKnowledge = knowledgeTerms.some(function (t) { return lower.includes(t); });

// RULE 4 — Final deterministic status
if (isKnowledge) {
  return {
    question: question,
    request_type: 'knowledge_query',
    priority: priority,
    status: 'approved_for_processing',
    reason: 'Company knowledge request',
    received_at: received_at,
  };
}

return {
  question: question,
  request_type: 'unsupported_query',
  priority: priority,
  status: 'unsupported',
  reason: 'Not identified as a company knowledge request',
  received_at: received_at,
};

