// Structured output parser wraps the model result under `output`.
const out = ($json && $json.output) ? $json.output : $json;

const fallback = {
  answer: 'Information not available in the knowledge base.',
  source: '',
  status: 'not_found',
};

let answer = out ? out.answer : undefined;
let source = out ? out.source : undefined;
let status = out ? out.status : undefined;

let valid = true;
// answer exists and is a string
if (typeof answer !== 'string' || answer.trim() === '') valid = false;
// status exists and is one of the allowed values
if (status !== 'answered' && status !== 'not_found') valid = false;
// source must be a string; if a source is missing on an answered result, default to empty
if (typeof source !== 'string') source = '';

let result;
if (!valid) {
  result = { answer: fallback.answer, source: fallback.source, status: fallback.status };
} else {
  result = { answer: answer, source: source, status: status };
}

// Business context for escalation decisions
const br = $('Apply Business Rules').item.json;
const question = br.question || '';
const priority = br.priority || 'Normal';
const lower = question.toLowerCase();

const humanTerms = ['human', 'agent', 'representative', 'speak to someone', 'talk to a person', 'talk to someone', 'escalate', 'manager', 'real person'];
const sensitiveTerms = ['salary', 'termination', 'terminate', 'fired', 'legal', 'lawsuit', 'harassment', 'complaint', 'discrimination', 'resignation'];
const wantsHuman = humanTerms.some(function (t) { return lower.includes(t); });
const sensitive = sensitiveTerms.some(function (t) { return lower.includes(t); });

let escalate = false;
let escalation_reason = '';
if (result.status === 'not_found') {
  escalate = true;
  escalation_reason = 'AI could not answer from the knowledge base';
} else if (wantsHuman) {
  escalate = true;
  escalation_reason = 'User explicitly requested human assistance';
} else if (sensitive) {
  escalate = true;
  escalation_reason = 'Request falls into a sensitive category requiring human review';
} else if (priority === 'High') {
  escalate = true;
  escalation_reason = 'High priority request requires human review';
}

// Empty / zero-item AI output: preserve the specific empty-response reason.
if ($json && $json.empty_ai_output === true) {
  escalate = true;
  escalation_reason = 'AI returned an empty response';
}

return {
  answer: result.answer,
  source: result.source,
  status: result.status,
  question: question,
  priority: priority,
  escalate: escalate,
  escalation_reason: escalation_reason,
};

