// Always build the clean final response from the validated AI result.
const v = $('Validate AI Response').item.json;
const status = v.status;
const answer = v.answer;
const source = v.source || '';
const escalated = v.escalate === true;

// Include reviewer decision when this item passed through Human Approval.
let human_approved = null;
try {
  const ha = $('Human Approval').item.json;
  if (ha && ha.data && typeof ha.data.approved !== 'undefined') {
    human_approved = ha.data.approved;
  }
} catch (e) {
  human_approved = null;
}

if (status === 'answered') {
  return {
    success: true,
    answer: answer,
    source: source,
    status: 'answered',
    escalated: escalated,
    human_approved: human_approved,
  };
}

return {
  success: false,
  answer: 'Information not available in the knowledge base.',
  source: '',
  status: 'not_found',
  escalated: escalated,
  human_approved: human_approved,
};

// Deterministic safe fallback for an EMPTY / zero-item AI response.
// Never expose internals; flows into Validate AI Response so the existing
// escalation / human approval / final response mechanism handles it.
return {
  answer: 'Information not available in the knowledge base.',
  source: '',
  status: 'not_found',
  escalate: true,
  escalation_reason: 'AI returned an empty response',
  empty_ai_output: true,
};

// Do NOT reference the incoming error object — that could leak internals.
return {
  success: false,
  answer: 'Sorry, the assistant is temporarily unavailable. Please try again shortly.',
  source: '',
  status: 'error',
};

return {
  success: false,
  message: 'This request is outside the company knowledge scope.',
  status: 'unsupported',
};

return {
  success: false,
  message: 'Please provide a more detailed question.',
  status: 'rejected',
};

return {
  success: false,
  error: 'Please provide a valid question.',
};
